import numpy as np
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
ps=[0,0.5,1,1.5,2,3]
G={'1':np.ones_like(t),'t':t,'t2':t*t,'t3':t**3,'exp(-t)':np.exp(-t),'1/t':1/t}
for w in [0.5,1,1.5,2,3,0.25,0.3,0.35,0.4]:
    G[f'cos{w}t']=np.cos(w*t); G[f'sin{w}t']=np.sin(w*t)
lib={}
for a in ps:
    for b in ps:
        for gk,gv in G.items():
            lib[f'x^{a}v^{b}*{gk}']=x**a*v**b*gv
names=list(lib); Mx=np.column_stack([lib[n] for n in names])
sel=[]; 
for step in range(10):
    best=None
    for j in range(len(names)):
        if j in sel: continue
        M=Mx[:,sel+[j]]
        c=np.linalg.lstsq(M,y,rcond=None)[0]; r=y-M@c
        e=np.mean(r**2)/np.var(y)
        if best is None or e<best[0]: best=(e,j)
